(function(){
'use strict';
const $=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)],E=FM.esc;
const KEY='force-multiplier-universal-v22';
const VERSION='22.1';
const CONTEXTS=[{id:'equipment',name:'Equipment services',asset:'unit',assets:'units',job:'booking',jobs:'bookings',org:'Northstar Services'},{id:'delivery',name:'Delivery operations',asset:'vehicle',assets:'vehicles',job:'delivery',jobs:'deliveries',org:'Harbor Delivery'},{id:'production',name:'Production operations',asset:'machine',assets:'machines',job:'order',jobs:'orders',org:'Cedar Works'}];
const DIMS=[['Discover','Find the relevant facts, requirements and gaps.'],['Evaluate','Check evidence and identify constraints and assumptions.'],['Decide','Choose a feasible response and explain the tradeoffs.'],['Act','Produce a correct and usable work product.'],['Communicate','Give another person the information needed to act.'],['Defend','Explain the reasoning and adapt to a new challenge.']];
const SCALE=['0 · Not demonstrated','1 · Needs direction','2 · Needs consequential corrections','3 · Independent','4 · Transfers and adapts'];
const TRACK_ORDER=['scheduling','analysis','documentation','dbm','integrity'];
const TRACKS=TRACK_ORDER.map(id=>FM_TRACKS.find(t=>t.id===id)).filter(Boolean);
const COLORS={scheduling:['#edf2dd','#688437'],analysis:['#e7eef6','#4f7295'],documentation:['#f6eddf','#9c7844'],dbm:['#ede8f3','#806699'],integrity:['#e3efe9','#4d8771']};
const defaults=()=>({schema:3,settings:{sound:true,context:'equipment',mode:'practice',calcPractice:true},cases:{},evidence:[],previewEvidence:[],notes:'',last:{track:'scheduling',lesson:0},lab:{kind:'trend',x:'12, 14, 13, 16, 17, 19, 18, 22',y:'15, 14, 16, 18, 17, 21, 20, 23'},createdAt:new Date().toISOString()});
let state=defaults(),storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.schema===3&&saved.settings&&saved.cases&&Array.isArray(saved.evidence)){state={...defaults(),...saved,settings:{...defaults().settings,...saved.settings}};}}catch(e){storageAvailable=false;}
if(!CONTEXTS.some(x=>x.id===state.settings.context))state.settings.context='equipment';
if(!['practice','independent','preview'].includes(state.settings.mode))state.settings.mode='practice';
if(!Array.isArray(state.previewEvidence))state.previewEvidence=[];
const allEvidence=()=>[...state.evidence,...state.previewEvidence];
let route={page:'home'},active=null,menu=false,fullscreen=false,currentFeedback=null,modalRecord=null,installPrompt=null,timer=Date.now(),toastTimer;
const id=()=>globalThis.crypto?.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9);
const seed=()=>{const a=new Uint32Array(1);if(globalThis.crypto?.getRandomValues){crypto.getRandomValues(a);return a[0];}return Math.floor(Math.random()*4294967296);};
const context=()=>CONTEXTS.find(x=>x.id===state.settings.context)||CONTEXTS[0];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;}catch(e){storageAvailable=false;}}
const date=s=>new Date(s).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const time=ms=>{const n=Math.max(0,Math.round(ms/1000));return `${Math.floor(n/60)}m ${n%60}s`;};
const getTrack=id=>TRACKS.find(x=>x.id===id);
const caseKey=(track,lesson,ctx=state.settings.context,mode=state.settings.mode)=>[track,lesson,ctx,mode].join('|');
function getCase(track,lesson){const key=caseKey(track.id,lesson.id);let c=state.cases[key];if(!c){c={seed:seed(),answers:{},attempts:0,hints:0,assisted:false,example:false,elapsed:0,startedAt:new Date().toISOString(),result:null};state.cases[key]=c;save();}return c;}
function recordsFor(t,l){return state.evidence.filter(e=>e.track===t&&(!l||e.lessonId===l));}
function passed(t,l){return recordsFor(t,l).some(e=>e.pass&&e.mode!=='preview');}
function independent(e){return e.mode==='independent'&&!e.assisted&&e.attemptNo===1;}
function reviewed(e){return independent(e)&&e.pass&&e.capstone&&e.review?.type==='peer'&&e.review?.criticalClear&&DIMS.every(([d])=>Number(e.review.scores[d])>=3);}
function pilotMet(t){const good=recordsFor(t).filter(reviewed);return new Set(good.map(e=>e.seed)).size>=2&&new Set(good.map(e=>e.contextId)).size>=2;}
const progress=t=>t.lessons.filter(l=>passed(t.id,l.id)).length;
function icon(name,cls=''){const p={home:'<path d="m3 10 9-7 9 7v11H3z"/><path d="M9 21v-8h6v8"/>',scheduling:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-13 4h3m3 0h3m-9 4h3"/>',analysis:'<path d="M4 3v18h17M8 17v-5m5 5V7m5 10V4"/>',documentation:'<path d="M14 3H5v18h14V8zM14 3v6h5M8 13h8m-8 4h5"/>',dbm:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 4 16 4 16 0V5M4 12v7c0 4 16 4 16 0v-7"/>',integrity:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z"/><path d="m8 12 3 3 5-6"/>',evidence:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="m8 9 2 2 5-5M8 15h8m-8 3h5"/>',standards:'<path d="M12 3v18M4 6h16M5 6l-3 8h6zM19 6l-3 8h6zM7 21h10"/>',guide:'<path d="M12 5v16M12 5C9 3 6 2 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-4-2-7-1-10 1z"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="10" cy="18" r="2" fill="currentColor"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',sound:'<path d="M11 4 6 8H3v8h3l5 4zM15 8c3 2 3 6 0 8m3-11c5 4 5 10 0 14"/>',muted:'<path d="M11 4 6 8H3v8h3l5 4zm4 5 6 6m0-6-6 6"/>',expand:'<path d="M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4L19 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',calculator:'<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M7 5h10v4H7zm0 8h1m3 0h1m3 0h1m-9 4h1m3 0h1m3 0h1"/>',lab:'<path d="M8 3h8m-6 0v7L3 21h18l-7-11V3M7 15h10"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5m0 4h.01"/>'};return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${p[name]||p.guide}</svg>`;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function sound(ok=true,variant=0,force=false){if(!state.settings.sound&&!force)return;try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const a=new A(),tones=ok?[[523,659,784],[392,523,659],[659,784,1047]][variant%3]:[[330,262],[294,220],[349,247]][variant%3];tones.forEach((freq,i)=>{const o=a.createOscillator(),g=a.createGain();o.type=ok?'sine':'triangle';o.frequency.value=freq;o.connect(g);g.connect(a.destination);const at=a.currentTime+i*.11;g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(.075,at+.015);g.gain.exponentialRampToValueAtTime(.001,at+.22);o.start(at);o.stop(at+.23);});setTimeout(()=>a.close(),950);}catch(e){}}
function go(hash){location.hash=hash;}
function parseRoute(){const parts=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);if(!parts.length){route={page:'home'};return;}if(parts[0]==='path'&&getTrack(parts[1])){route={page:parts[2]===undefined?'path':'lesson',track:parts[1],index:Math.max(0,Math.min(Number(parts[2])||0,getTrack(parts[1]).lessons.length-1))};}else route={page:['home','standards','evidence','guide','settings','lab'].includes(parts[0])?parts[0]:'home'};}
const button=(text,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
function contextControl(){return `<div class="context-select"><label for="context">Practice context</label><select id="context" aria-label="Practice context">${CONTEXTS.map(c=>`<option value="${c.id}" ${context().id===c.id?'selected':''}>${c.name}</option>`).join('')}</select></div>`;}
function render(preserve=false){const y=window.scrollY;active=null;parseRoute();const title=route.track?getTrack(route.track).title:({home:'Learning workspace',standards:'What success looks like',evidence:'Evidence portfolio',guide:'Field guide',settings:'Your workspace',lab:'Statistics lab'}[route.page]);
document.body.classList.toggle('menu-open',menu);document.body.classList.toggle('fullscreen',fullscreen);
$('#app').innerHTML=`<div class="menu-shade" data-action="menu"></div><aside class="sidebar"><a href="#home" class="brand"><span class="brand-symbol">F<span style="font-size:14px;margin-left:-2px">×</span></span><span class="brand-text">Force Multiplier<small>Practical skills · v22</small></span></a><nav aria-label="Main navigation"><button class="nav-btn ${route.page==='home'?'active':''}" data-nav="home">${icon('home')}Overview</button><div class="nav-label">Your specialties</div>${TRACKS.map(t=>`<button class="nav-btn ${route.track===t.id?'active':''}" data-nav="path/${t.id}">${icon(t.id)}${E(t.title)}<span class="nav-count">${progress(t)}/${t.lessons.length}</span></button>`).join('')}<div class="nav-label">Practice & evidence</div>${[['lab','Statistics lab'],['evidence','Evidence portfolio'],['standards','Success standard'],['guide','Field guide']].map(([p,n])=>`<button class="nav-btn ${route.page===p?'active':''}" data-nav="${p}">${icon(p)}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><strong>Build the work. Explain the why.</strong><p>Start small. Practice with change.<br>Show what you can do independently.</p><button class="nav-btn ${route.page==='settings'?'active':''}" data-nav="settings" style="padding-left:0;margin-top:15px">${icon('settings')}Workspace settings</button><div class="version">UNIVERSAL EDITION <span class="pill dark" style="margin-left:7px">22.1</span></div></div></aside><div class="app-main"><header class="topbar"><div class="breadcrumbs">${button(icon('menu'),'menu','ghost mobile-menu','aria-label="Open navigation"')}<span>Workspace</span><span>/</span><strong>${E(title)}</strong></div><div class="top-actions">${button(icon(state.settings.sound?'sound':'muted')+`<span class="sound-label">Sound ${state.settings.sound?'on':'off'}</span>`,'sound','small ghost',`aria-pressed="${state.settings.sound}" aria-label="Toggle sound"`)}${button(icon('download')+'<span class="desktop-label">Install app</span>','install','small','aria-label="Install app"')}</div></header><main id="main" class="content" tabindex="-1">${pageContent()}</main></div>`;
if(!storageAvailable)$('#main').insertAdjacentHTML('afterbegin','<div class="notice warn">Browser storage is unavailable or full. Your current work is available in this session; export a backup to retain it.</div>');
document.title=(route.track?getTrack(route.track).title:title)+' · Force Multiplier';
bindLocal();if(preserve)requestAnimationFrame(()=>window.scrollTo(0,y));else window.scrollTo(0,0);
}
function pageContent(){switch(route.page){case'path':return pathPage();case'lesson':return lessonPage();case'evidence':return evidencePage();case'standards':return standardsPage();case'guide':return guidePage();case'settings':return settingsPage();case'lab':return labPage();default:return homePage();}}
function homePage(){const practiced=new Set(state.evidence.filter(e=>e.mode!=='preview').map(e=>e.track+'|'+e.lessonId)).size,ind=new Set(state.evidence.filter(e=>independent(e)&&e.pass).map(e=>e.track+'|'+e.lessonId)).size,rev=TRACKS.filter(t=>pilotMet(t.id)).length;let last=state.last;if(!getTrack(last.track))last={track:'scheduling',lesson:0};return `<div class="intro-row"><div><div class="eyebrow">Your learning workspace</div><p style="margin-top:7px;font-size:13px">Five practical skills. One standard: show the work.</p></div><span class="pill"><span class="dot"></span> Progress stays on this device</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">Learn by doing</div><h1>Build the skill.<br><span class="serif">Prove it in practice.</span></h1><p>Turn information into decisions people can use. Start with one small task, then build up to realistic work, changing conditions, and independent performance.</p><div class="hero-actions">${button((practiced?'Continue practice':'Start with scheduling')+icon('arrow'),'resume','primary')}<button class="link-btn" data-nav="standards">What counts as success?</button></div></div><div class="hero-art" aria-hidden="true"><div class="artifact-card"><div class="row"><span>WEEKLY RESOURCE PLAN</span><span>01 / 05</span></div><div class="mini-schedule"><span class="label"></span><span>M</span><span>T</span><span>W</span><span>T</span><span>F</span>${['A','B','C'].map((a,i)=>`<span class="label">Unit ${a}</span>${[0,1,2,3,4].map(j=>`<span class="${(j+i)%4===1?'reserve':'job'}">${(j+i)%4===1?'R':'✓'}</span>`).join('')}`).join('')}</div></div><div class="artifact-card mini-check"><b>✓</b><div><strong>An executable plan</strong><small>Constraints checked. Decisions explained.</small></div></div><p class="hero-note">MAKE SOMETHING THAT WORKS.</p></div></section><section class="stats" aria-label="Your progress"><div class="stat"><strong>${practiced}</strong><div><b>Lessons practiced</b><span>Across ${TRACKS.length} specialties</span></div></div><div class="stat"><strong>${ind}</strong><div><b>Independent technical passes</b><span>Fresh case · first submission</span></div></div><div class="stat"><strong>${rev}/5</strong><div><b>Pilot criteria recorded</b><span>Two contexts + peer review</span></div></div></section><div class="section-head"><div><h2>Choose a specialty</h2><p>Begin at the foundations or jump to a specific skill.</p></div>${contextControl()}</div><section class="paths">${TRACKS.map(t=>{const c=COLORS[t.id],n=progress(t);return `<article class="path-row"><div class="path-icon" style="background:${c[0]};color:${c[1]}">${icon(t.id)}</div><div><h3>${E(t.title)}</h3><p>${E(t.description)}</p></div><div class="path-progress"><small>${n} of ${t.lessons.length} technical passes</small><div class="progress"><i style="width:${100*n/t.lessons.length}%;background:${c[1]}"></i></div><small>Foundation → capstone</small></div><button class="btn small" data-nav="path/${t.id}"><span>Explore</span>${icon('arrow')}</button></article>`;}).join('')}</section><div class="home-footer"><section class="insight"><div class="eyebrow">The performance framework</div><h3>Discover → Evaluate → Decide → Act → Communicate → Defend</h3><p>Every capstone ends with an actual work product, a recommendation, and a defense of the decisions behind it.</p></section><section class="insight"><div class="eyebrow">Built for transfer</div><h3>Same principles. Different workplaces.</h3><p>Practice in equipment services, delivery operations, or production. Change the context to test what carries over.</p><button class="link-btn" data-nav="evidence">Open your evidence portfolio →</button></section></div>`;}
function pathPage(){const t=getTrack(route.track),n=progress(t);return `<div class="intro-row"><div><div class="eyebrow">${E(t.kicker||'A practical learning path')}</div><h1>${E(t.title)}</h1><p>${E(t.outcome)}</p></div>${contextControl()}</div><div class="track-overview"><section class="lesson-list">${t.lessons.map((l,i)=>{const done=passed(t.id,l.id);return `<article class="lesson-row ${done?'done':''}"><div class="lesson-number">${done?'✓':String(i+1).padStart(2,'0')}</div><div><h3>${E(l.title)}</h3><p>${E(l.summary)}</p><div class="lesson-tags"><span class="pill ${l.level==='Capstone'?'warn':'neutral'}">${E(l.level)}</span><span>~${l.minutes} min practice</span>${done?'<span>Technical check passed</span>':''}</div></div><button class="btn small ${i===0&&!done?'primary':''}" data-nav="path/${t.id}/${i}">${done?'Practice again':'Open'}</button></article>`;}).join('')}</section><aside><div class="panel highlight"><div class="eyebrow">Build from the ground up</div><h3 style="margin-top:9px">A little more capable,<br>one task at a time.</h3><p>Each lesson adds a new decision or constraint. The final task brings the skills together in an unfamiliar case.</p><div class="progress" style="margin-top:20px"><i style="width:${n/t.lessons.length*100}%"></i></div><p style="font-size:11px">${n} of ${t.lessons.length} lessons with a technical pass</p></div><div class="panel"><h3>Three ways to work</h3><ul><li><strong>Practice:</strong> learn with hints and worked examples.</li><li><strong>Independent check:</strong> a fresh case without answers or hints.</li><li><strong>Coach preview:</strong> inspect the path and fill example solutions.</li></ul><div class="notice">Practice completion is useful. Independent performance is the evidence we are looking for.</div><button class="link-btn" data-nav="standards">Read the proposed success standard →</button></div></aside></div>`;}
function fieldHTML(f,a){const val=a[f.id]??'',attrs=`data-field="${E(f.id)}" id="f-${E(f.id)}"`;let input='';if(f.kind==='select'){input=`<select ${attrs}><option value="">Choose…</option>${(f.options||[]).map(o=>{if(typeof o==='string')o={value:o,label:o};return `<option value="${E(o.value)}" ${String(val)===String(o.value)?'selected':''}>${E(o.label)}</option>`;}).join('')}</select>`;}else if(f.kind==='textarea')input=`<textarea ${attrs} rows="3" maxlength="8000" placeholder="${E(f.placeholder||'Write your answer')}">${E(val)}</textarea>`;else if(f.kind==='checkbox')input=`<input type="checkbox" ${attrs} ${val===true?'checked':''}>`;else input=`<input ${attrs} type="${f.kind==='number'?'number':'text'}" value="${E(val)}" ${f.kind==='number'?`step="${f.step??'any'}" inputmode="decimal" ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined?`max="${f.max}"`:''}`:'maxlength="1000"'} autocomplete="off" placeholder="${E(f.placeholder||'Enter value')}">`;
return `<div class="field ${f.wide||f.kind==='textarea'?'wide':''}"><label for="f-${E(f.id)}">${E(f.label)}</label><div class="input-wrap">${input}${f.unit?`<span class="unit">${E(f.unit)}</span>`:''}</div>${f.help?`<small>${E(f.help)}</small>`:''}</div>`;}
function fieldsHTML(fields,a){let group=null;return `<div class="field-grid">${fields.map(f=>{let h='';if(f.group&&f.group!==group){group=f.group;h=`<div class="field-group">${E(group)}</div>`;}return h+fieldHTML(f,a);}).join('')}</div>`;}
function tableHTML(t){return `<section class="source-block"><h3>${E(t.title||'Source information')}</h3><div class="table-wrap"><table><thead><tr>${t.headers.map(h=>`<th scope="col">${E(h)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(row=>`<tr>${row.map(c=>`<td>${E(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function lessonPage(){const t=getTrack(route.track),l=t.lessons[route.index],c=getCase(t,l),sc=l.build(c.seed,context());active={t,l,c,sc,key:caseKey(t.id,l.id)};state.last={track:t.id,lesson:route.index};if(t.id==='analysis'&&!state.settings.calcPractice&&state.settings.mode==='practice'&&!c.calcInitialized){sc.fields.filter(f=>f.kind==='number').forEach(f=>{c.answers[f.id]=sc.model[f.id]??'';});c.calcProvided=true;c.calcInitialized=true;c.assisted=true;}save();const capstone=!!(sc.capstone||l.level==='Capstone'||l.capstone);active.capstone=capstone;const mode=state.settings.mode;const modelLabel='Show Me the Right Answer';return `<div class="lesson-top"><div class="lesson-title"><div class="eyebrow"><button class="link-btn" data-nav="path/${t.id}">${E(t.title)}</button> <span style="margin:0 6px">/</span> ${route.index+1} of ${t.lessons.length}</div><h1>${E(l.title)}</h1><div class="meta"><span class="pill ${capstone?'warn':'neutral'}">${E(l.level)}</span><span>${E(context().name)}</span><span>Case ${c.seed.toString(16).toUpperCase().padStart(8,'0')}</span><span id="elapsed">${time(c.elapsed||0)}</span></div></div><div class="toolbar"><select id="lesson-jump" aria-label="Jump to lesson">${t.lessons.map((x,i)=>`<option value="${i}" ${i===route.index?'selected':''}>${i+1}. ${E(x.title)}</option>`).join('')}</select>${button(icon('expand'),'fullscreen','small','aria-label="Toggle full-screen workspace"')}</div></div><div class="mode-strip"><div class="segmented" aria-label="Training mode">${[['practice','Practice'],['independent','Independent check'],['preview','Coach preview']].map(([m,n])=>`<button data-mode="${m}" class="${m===mode?'active':''}" aria-pressed="${m===mode}">${n}</button>`).join('')}</div><span class="mode-caption">${mode==='practice'?'Build understanding with feedback and worked examples.':mode==='independent'?'Fresh cases, no hints. First submissions are retained.':'Demonstrations have separate work and never earn proficiency.'}</span>${button(icon('back')+'Exit full screen','fullscreen','small fs-exit')}</div>${mode==='preview'?'<div class="notice warn">Coach preview · Example solutions and demonstrations are separate from learner evidence.</div>':''}${c.assisted?'<div class="notice warn">Assisted practice · Hints, supplied calculations, or an example have been used in this case.</div>':''}<div class="work-layout"><section class="work-sheet"><div class="sheet-header"><div class="case-label"><span>Your assignment</span><span>${E(context().org)}</span></div><h2>${capstone?'Build the complete work product':'Start with this task'}</h2><p>${E(sc.brief)}</p>${sc.facts?.length?`<div class="facts">${sc.facts.map(f=>`<div class="fact"><span>${E(f.label)}</span><strong>${E(f.value)}</strong></div>`).join('')}</div>`:''}</div><div class="sheet-body">${(sc.tables||[]).map(tableHTML).join('')}${sc.visual?`<div class="visual">${sc.visual}</div>`:''}<h3 class="task-heading">Your work</h3><form id="work-form" autocomplete="off">${fieldsHTML(sc.fields,c.answers)}${capstone?`<h3 class="task-heading">Communicate & defend</h3><p class="muted" style="font-size:12px;margin-bottom:18px">These explanations are recorded for human review. The app does not judge the quality of prose.</p>${fieldsHTML([{id:'_recommendation',label:'What should happen next, and who needs to act?',kind:'textarea',placeholder:'State your decision, owner, next action and timing.'},{id:'_evidence',label:'What evidence supports your decision?',kind:'textarea',placeholder:'Use specific values, sources, constraints and tradeoffs from this case.'},{id:'_defense',label:'What could change your decision?',kind:'textarea',placeholder:'Explain a limitation, an alternative, and what you would check if conditions changed.'}],c.answers)}`:''}</form></div><div class="sheet-actions"><div>${button(icon('check')+(mode==='independent'?'Submit independent work':'Check my work'),'check','primary')}${button(icon('calculator'),'calculator','','aria-label="Open calculator"')}</div><div>${button('Re-simulate Question','new-case','small')}${button('Clear this worksheet','clear-case','small ghost')}</div></div><div id="feedback-region" aria-live="polite">${c.result?feedbackHTML(c.result,sc):''}</div></section><aside class="work-side"><div class="panel"><div class="eyebrow">The skill behind the task</div><h3 style="margin-top:9px">${E(l.summary)}</h3>${mode==='independent'?'<p>Your work is being recorded as an independent check. Use the source information and constraints in the assignment.</p>':`<ol>${(sc.teach||[]).map(s=>`<li>${E(s)}</li>`).join('')}</ol>`}${button('Get a hint','hint','',mode==='independent'?'disabled title="Hints are available in Practice mode"':'')}${button(modelLabel,'model','',mode==='independent'?'disabled title="Worked examples are available in Practice or Coach preview"':'')}${t.id==='analysis'&&mode==='practice'?button(`Calculation practice: ${state.settings.calcPractice?'on':'off'}`,'calculation-mode','small'):''}<div class="framework">${DIMS.map(([n])=>`<span>${n}</span>`).join('')}</div></div><div class="panel highlight"><h3>${capstone?'What success looks like':'Make the learning stick'}</h3><p>${capstone?'Meet every critical constraint, produce a usable result, then explain your decisions. A peer reviewer scores the six performance dimensions.':'After you understand this example, try a new case without hints. Change the context to see whether the skill transfers.'}</p>${capstone?'<div class="notice" style="font-size:11px">Objective checks can pass while explanations still await review.</div>':''}<button class="link-btn" data-nav="${capstone?'standards':'evidence'}">${capstone?'See the pilot assessment rubric':'See your saved evidence'} →</button></div></aside></div><div class="footer-nav"><button class="btn" data-nav="${route.index?'path/'+t.id+'/'+(route.index-1):'path/'+t.id}">${icon('back')}${route.index?'Previous lesson':'Learning path'}</button><button class="btn" data-nav="${route.index+1<t.lessons.length?'path/'+t.id+'/'+(route.index+1):'evidence'}">${route.index+1<t.lessons.length?'Next lesson':'Evidence portfolio'}${icon('arrow')}</button></div><p class="workspace-footer">Synthetic practice · Decisions affect this training workspace only · Case progress saves automatically</p>`;}
function feedbackHTML(result,sc){const pass=result.pass;return `<section class="feedback"><h3>${pass?'🙂 Objective checks passed':'🙁 There is more to resolve'}</h3><p>${result.mode==='preview'?'Coach demonstration — not learner proficiency.':result.mode==='independent'&&result.attemptNo>1?'Revised after feedback. Start a new case for another first-attempt independent check.':result.assisted?'Assisted practice recorded. Try a fresh independent case next.':result.mode==='independent'?'Independent first submission retained in your evidence portfolio.':'Practice recorded. Use an independent check to gather unassisted evidence.'} ${result.capstone&&pass?'Explanation awaiting peer review.':''}</p><div class="feedback-list">${result.checks.map(c=>`<div class="check ${c.ok?'good':'bad'} ${c.critical?'critical':''}"><span>${c.ok?'✓':'!'}</span><div><strong>${E(c.label)}${c.critical&&!c.ok?' · critical constraint':''}</strong><p>${E(c.feedback||'')}</p></div></div>`).join('')}</div>${sc.debrief?`<div class="debrief"><strong>Why this matters</strong><br>${E(sc.debrief)}</div>`:''}${result.capstone?`<div style="margin-top:15px">${button('Review this work product','review-record','small',`data-record="${E(result.id)}"`)}</div>`:''}</section>`;}
function checkWork(){if(!active)return;if(state.settings.mode!=='preview'&&state.evidence.length>=500){openModal('Evidence portfolio is full','<p>Your 500 learner submissions have been retained. Export a workspace backup before resetting this local workspace for further training.</p>'+button('Export workspace backup','backup','primary'));return;}const{t,l,c,sc,capstone}=active;const checks=sc.check({...c.answers});if(!Array.isArray(checks)||!checks.length){toast('This case could not be checked. Please start a new case.');return;}c.attempts++;const pass=checks.every(x=>x.ok);const record={id:id(),version:VERSION,track:t.id,trackTitle:t.title,lessonId:l.id,lessonTitle:l.title,level:l.level,capstone,contextId:context().id,contextName:context().name,seed:c.seed,mode:state.settings.mode,assisted:!!c.assisted,calcProvided:!!c.calcProvided,hints:c.hints||0,example:!!c.example,attemptNo:c.attempts,startedAt:c.startedAt,submittedAt:new Date().toISOString(),elapsedMs:c.elapsed||0,answers:{...c.answers},fields:sc.fields.map(f=>({id:f.id,label:f.label,kind:f.kind,options:f.options})),brief:sc.brief,facts:sc.facts||[],tables:sc.tables||[],checks,pass,review:null};if(record.mode==='preview'){state.previewEvidence.push(record);if(state.previewEvidence.length>50)state.previewEvidence=state.previewEvidence.slice(-50);}else state.evidence.push(record);c.result={id:record.id,checks,pass,mode:record.mode,assisted:record.assisted,capstone,attemptNo:record.attemptNo};c.lastEvidence=record.id;save();$('#feedback-region').innerHTML=feedbackHTML(c.result,sc);sound(pass,c.attempts%3);const target=$('#feedback-region');if(target.getBoundingClientRect().top>window.innerHeight-80)target.scrollIntoView({behavior:'smooth',block:'start'});toast(pass?(capstone?'Technical checks passed. Explanation is ready for review.':'Technical checks passed. Your attempt is saved.'):'Feedback saved. Review the checks below.');}
function evidencePage(){const list=allEvidence().sort((a,b)=>new Date(b.submittedAt)-new Date(a.submittedAt)),ind=state.evidence.filter(e=>independent(e)&&e.pass).length;return `<div class="intro-row"><div><div class="eyebrow">Performance you can review</div><h1>Evidence portfolio</h1><p>Work products, first attempts, assistance, time, and reviewer judgments. Practice and demonstrations stay clearly identified.</p></div><div class="toolbar">${button(icon('download')+'Export evidence','export-evidence','small')}${button('Print','print','small')}</div></div><div class="stats"><div class="stat"><strong>${state.evidence.length}</strong><div><b>Saved submissions</b><span>Up to 500 learner submissions</span></div></div><div class="stat"><strong>${ind}</strong><div><b>Independent technical passes</b><span>First submission on a case</span></div></div><div class="stat"><strong>${state.evidence.filter(reviewed).length}</strong><div><b>Peer-reviewed capstones</b><span>Meet the proposed rubric</span></div></div></div><div class="panel highlight"><h3>Evidence of transfer</h3><p>The proposed pilot criterion requires two fresh, independent capstones in different contexts, all objective checks passed, and a peer rating of at least 3 in every dimension. These are proposed evaluation rules, not a validated credential.</p><div class="evidence-metrics" style="margin-top:15px">${TRACKS.map(t=>`<span class="pill ${pilotMet(t.id)?'passed':'neutral'}">${pilotMet(t.id)?'✓':'○'} ${E(t.title)}</span>`).join('')}</div></div>${!list.length?`<section class="empty">${icon('evidence')}<h3>Your work will tell the story.</h3><p>Complete an exercise and submit your work. Each submission keeps the case, your answers, the checks, and whether you used help.</p><button class="btn primary" data-nav="path/scheduling/0">Begin the first task ${icon('arrow')}</button></section>`:`<section class="evidence-list">${list.map(e=>`<article class="evidence-row"><div><h3>${E(e.trackTitle)} · ${E(e.lessonTitle)}</h3><div class="evidence-metrics"><span class="pill ${e.pass?'passed':'warn'}">${e.pass?'Technical pass':'Needs work'}</span><span class="pill ${independent(e)?'blue':'neutral'}">${e.mode==='preview'?'Coach preview':independent(e)?'Independent first attempt':e.mode==='independent'?'Revised after feedback':e.assisted?'Assisted practice':'Practice'}</span>${e.capstone?`<span class="pill ${reviewed(e)?'passed':'neutral'}">${e.review?(reviewed(e)?'Peer rubric met':e.review.type==='self'?'Self review':'Review recorded'):'Review pending'}</span>`:''}</div><p>${E(e.contextName)} · ${date(e.submittedAt)} · ${time(e.elapsedMs)} visible practice time · Case ${e.seed.toString(16).toUpperCase()} · attempt ${e.attemptNo}</p></div><div class="toolbar">${button('View work','view-record','small',`data-record="${E(e.id)}"`)}${e.capstone?button('Review','review-record','small',`data-record="${E(e.id)}"`):''}</div></article>`).join('')}</section>`}<p class="workspace-footer">Time is measured while the exercise is visible. Entries and reviewer identities are local records, not externally verified credentials.</p>`;}
function standardsPage(){return `<div class="intro-row"><div><div class="eyebrow">The answer to the background paper</div><h1>What does success look like?</h1><p>A shared definition for learners, trainers, and the working group.</p></div>${button('Print standard','print','small')}</div><div class="definition">A learner succeeds when they can independently produce a correct, usable work product from unfamiliar information, respond to a meaningful change, and explain the evidence and tradeoffs behind their decisions.</div><section class="standards"><div class="panel full"><h3>Six observable dimensions</h3><div class="table-wrap rubric-table" style="margin-top:18px"><table><thead><tr><th>Dimension</th><th>What an evaluator should see</th></tr></thead><tbody>${DIMS.map(([n,d])=>`<tr><td>${n}</td><td>${d}</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><h3>A usable product in every specialty</h3><ul><li><strong>Scheduling:</strong> a feasible resource plan, revised after a disruption.</li><li><strong>Analysis:</strong> validated measures, appropriate comparisons, a supported recommendation.</li><li><strong>Documentation:</strong> a reconciled requirement register, forecast and verified closeout.</li><li><strong>Database management:</strong> an authorized access plan and verified incident recovery.</li><li><strong>Data integrity:</strong> corrected records with source evidence and an audit trail.</li></ul></div><div class="panel"><h3>Critical errors cannot average away</h3><ul><li>No unavailable or double-booked resources.</li><li>No incorrect metric denominator, invented evidence or causal claim from correlation alone.</li><li>No unsupported completion, lost traceability or ignored required action.</li><li>No excessive access or unverified recovery.</li><li>No fabricated missing values or deletion of valid records.</li></ul></div></section><div class="section-head" style="margin-top:30px"><div><h2>The proposed reviewer scale</h2><p>Score each dimension separately. Calibrate examples with more than one evaluator.</p></div></div><div class="score-scale">${[['0','Not demonstrated','No usable result or a fundamental misconception.'],['1','Needs direction','Requires step-by-step help.'],['2','Partly independent','Needs consequential corrections.'],['3','Independent','Correct, usable work with sound explanation.'],['4','Transfers & adapts','Handles change and explains alternatives.']].map(([n,t,d])=>`<div><strong>${n}</strong><b>${t}</b><p>${d}</p></div>`).join('')}</div><div class="notice"><strong>Proposed pilot threshold:</strong> meet every critical constraint, pass the objective checks, and earn at least 3/4 in all six dimensions on two fresh independent capstones, including one in a different context. Worked examples, hints, supplied calculations, self reviews and coach demonstrations do not satisfy this threshold.</div><section class="standards" style="margin-top:24px"><div class="panel"><h3>Measure training effectiveness</h3><ol><li>Agree on essential tasks and critical errors before testing.</li><li>Collect a comparable baseline work product.</li><li>Train, then assess with fresh cases and different numbers.</li><li>Have qualified reviewers score the same work independently.</li><li>Repeat selected tasks after a delay to test retention.</li><li>Compare time to the same performance threshold.</li></ol></div><div class="panel highlight"><div class="eyebrow">Research goals, not results</div><h3 style="margin-top:10px">Four hours. Tenfold efficiency.</h3><p>These are hypotheses to test. Completing four hours of lessons does not establish proficiency or prove a tenfold improvement.</p><div class="notice">Efficiency ratio = comparison-group time to the agreed proficiency threshold ÷ app-group time to that same threshold.</div><p>Start experience, case difficulty, assistance rules, and review standards must be comparable. Report evaluator disagreements and remaining uncertainty.</p></div><div class="panel full"><h3>Working-group decisions</h3><p>What is missing from these five work products? Which errors are critical? What evidence would convince two independent reviewers? Use this space for your local review notes.</p><textarea id="working-notes" class="note-area" placeholder="Record proposed criteria, gaps, reviewer disagreements and pilot decisions…">${E(state.notes)}</textarea><div class="toolbar">${button('Copy notes','copy-notes','small')}${button('Export workspace backup','backup','small')}</div><small class="muted">Saved locally as you type.</small></div></section>`;}
const GENERIC_FORMULAS=[{name:'Rate or proportion',formula:'Rate = qualifying events ÷ defined exposure × scale',meaning:'State the event, eligible population, period, unit, and scale. A zero denominator is undefined; it is not a zero rate.',example:'3 failures over 120 completed jobs = 2.5 failures per 100 jobs.'},{name:'Maintenance downtime percentage',formula:'Maintenance downtime % = maintenance-unavailable asset-hours ÷ total asset-hours in scope × 100',meaning:'Both quantities must cover the same assets and time period. Define which overlapping causes are included before calculating.',example:'120 maintenance-unavailable hours ÷ 2,400 asset-hours × 100 = 5%.'},{name:'Combined unavailability',formula:'Unavailable hours = maintenance hours + parts-delay hours − overlapping hours',meaning:'When categories overlap, subtract the intersection once. Availability is 100% minus total unavailable share only when these causes cover all unavailability.',example:'80 maintenance + 50 parts delay − 20 overlap = 110 unavailable asset-hours.'},{name:'Timely repair percentage',formula:'Timely repair % = qualifying failures restored within the limit ÷ all qualifying failures in the defined cohort × 100',meaning:'Use the failure cohort, rather than completed jobs. State how the time limit and unresolved failures are handled.',example:'2 of 10 qualifying failures restored within 8 hours = 20%.'},{name:'Pooled rate',formula:'Pooled rate = sum of numerators ÷ sum of denominators × scale',meaning:'Sum the underlying counts before computing the pooled rate. An unweighted mean of percentages is wrong when exposures differ.',example:'(1 + 18) ÷ (10 + 90) × 100 = 19%, not the 15% average of 10% and 20%.'},{name:'Capacity and usable output',formula:'Usable capacity = available resources × productive time per resource',meaning:'Keep calendar time, staffed time and productive time separate. Deduct downtime, reserve and non-overlapping constraints consistently.',example:'4 units × 6 productive hours = 24 unit-hours before additional downtime.'},{name:'Remaining interval',formula:'Remaining allowance = due threshold − current usage',meaning:'Calculate the remaining allowance in the same unit as the requirement. A forecast needs an explicit future usage assumption.',example:'Service due at 500 hours; current reading 460 = 40 hours remaining.'},{name:'Time to agreed proficiency',formula:'Elapsed training time until the agreed performance threshold is demonstrated',meaning:'Compare equivalent tasks and entry experience. Distinguish time in a lesson from verified independent performance.',example:'Keep assistance, critical errors, transfer cases and reviewer scores alongside time.'}];
function guidePage(){const formulas=[...GENERIC_FORMULAS,...TRACKS.flatMap(t=>t.reference||[])];const unique=formulas.filter((x,i,a)=>a.findIndex(y=>y.name===x.name)===i);return `<div class="intro-row"><div><div class="eyebrow">Concepts that travel</div><h1>Field guide</h1><p>Plain definitions and explicit formulas. Each exercise states its own scope and assumptions.</p></div><button class="btn small" data-nav="lab">${icon('lab')}Open statistics lab</button></div><div class="notice">A familiar formula can answer the wrong question if its denominator, units, time period or population changes. Define the measure before calculating it.</div><section class="formula-grid">${unique.map(f=>`<article class="formula"><h3>${E(f.name)}</h3><code>${E(f.formula)}</code><p>${E(f.meaning||f.description||'')}</p>${f.example?`<p><strong>Example:</strong> ${E(f.example)}</p>`:''}</article>`).join('')}</section><section class="panel" style="margin-top:22px"><h3>Five specialties, distinct responsibilities</h3><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Specialty</th><th>The question you answer</th></tr></thead><tbody><tr><td>Scheduling</td><td>What can we do, with which resources, and when?</td></tr><tr><td>Analysis</td><td>What does the evidence show, and what decision does it support?</td></tr><tr><td>Documentation</td><td>What is required, does it apply, and is completion supported?</td></tr><tr><td>Database management</td><td>Who should have access, and can the system preserve and deliver trustworthy information?</td></tr><tr><td>Data integrity</td><td>Does the stored record accurately represent its verified source?</td></tr></tbody></table></div></section>`;}
function settingsPage(){return `<div class="intro-row"><div><div class="eyebrow">Make it work for you</div><h1>Your workspace</h1><p>Practice preferences, local progress, and a portable backup.</p></div></div><section class="settings-grid"><div class="panel"><h3>Practice settings</h3>${contextControl()}<div class="setting-row"><span>Feedback sounds<small>Generated on your device; no audio downloads.</small></span><input type="checkbox" id="sound-setting" aria-label="Feedback sounds" ${state.settings.sound?'checked':''}></div><div class="setting-row"><span>Practice calculations<small>Off supplies numerical answers in Analysis practice only. Independent checks always require your own work.</small></span><input type="checkbox" id="calc-setting" aria-label="Practice calculations" ${state.settings.calcPractice?'checked':''}></div><div class="toolbar">${[0,1,2].map(i=>button(`🙂 ${i+1}`,'test-sound','small',`data-ok="true" data-variant="${i}" aria-label="Play positive sound ${i+1}"`)).join('')}${[0,1,2].map(i=>button(`🙁 ${i+1}`,'test-sound','small',`data-ok="false" data-variant="${i}" aria-label="Play correction sound ${i+1}"`)).join('')}</div><p style="font-size:11px;margin-top:15px">Sound samples play when tapped, even if automatic feedback is off.</p></div><div class="panel"><h3>Open it like an app</h3><p>Install this workspace on your home screen for a focused experience. After the app has loaded and its offline files are ready, its exercises can work without a connection.</p>${button('Install / home-screen instructions','install','primary')}<div class="notice" id="offline-status">${navigator.serviceWorker?.controller?'Offline support is active in this browser.':'Offline support will activate after the application files finish loading.'}</div><p style="font-size:11px">Progress is saved in this browser on this device. Installing in another browser or clearing website data can create an empty workspace.</p></div><div class="panel"><h3>Back up your work</h3><p>A workspace backup keeps exercises, work products, reviewer notes and preferences. An evidence export keeps the submitted attempts for review.</p><div class="toolbar">${button('Workspace backup','backup','primary')}${button('Evidence only','export-evidence')}</div><label for="restore-file">Restore a workspace backup</label><input id="restore-file" type="file" accept="application/json,.json"><p style="font-size:11px;margin-top:10px">You will review the backup before replacing current local work.</p></div><div class="panel"><h3>About this edition</h3><p><strong>Force Multiplier · Universal edition ${VERSION}</strong><br>Progressive workplace simulations across five disciplines. All cases are fictional. Industry contexts change the setting; they do not supply organization-specific procedures.</p><p style="margin-top:13px">Built around independent performance, work products and human review. Automated checks verify modeled rules; they do not certify occupational competence.</p><button class="btn danger" data-action="reset-workspace">Reset this workspace</button><p style="font-size:11px;margin-top:10px">Reset affects only this app’s local data. Back up first if you want to retain your work.</p></div></section>`;}
function labPage(){return `<div class="intro-row"><div><div class="eyebrow">Explore the numbers</div><h1>Statistics lab</h1><p>Run an analysis on a small dataset, then examine what the result can and cannot support.</p></div><button class="btn small" data-nav="path/analysis">Guided analysis lessons ${icon('arrow')}</button></div><div class="work-layout"><section class="panel"><div class="segmented" style="margin-bottom:23px">${[['trend','Trend'],['correlation','Correlation'],['difference','Difference']].map(([k,n])=>`<button class="${state.lab.kind===k?'active':''}" data-lab-kind="${k}">${n}</button>`).join('')}</div><div class="field"><label for="lab-x">${state.lab.kind==='trend'?'Observations in time order':state.lab.kind==='correlation'?'X values (paired with Y in the same order)':'Group A observations'}</label><textarea id="lab-x" rows="4" placeholder="Separate numbers with commas, spaces or newlines">${E(state.lab.x)}</textarea></div>${state.lab.kind!=='trend'?`<div class="field" style="margin-top:16px"><label for="lab-y">${state.lab.kind==='correlation'?'Y values (one for each X value)':'Group B observations'}</label><textarea id="lab-y" rows="4" placeholder="Separate numbers with commas, spaces or newlines">${E(state.lab.y)}</textarea></div>`:''}<div class="toolbar" style="margin:20px 0">${button('Run analysis','run-lab','primary')}${button('New sample data','sample-lab')}</div><div id="lab-output" aria-live="polite"><div class="notice">Enter 3–500 finite numbers per series. Blank and malformed values are not silently converted to zero.</div></div></section><aside class="work-side"><div class="panel"><h3>${state.lab.kind==='trend'?'How is the process changing?':state.lab.kind==='correlation'?'Do the variables move together?':'How do the group averages differ?'}</h3><p>${state.lab.kind==='trend'?'A trend uses the order of observations. A fitted slope describes change per time step; it does not establish the cause of that change.':state.lab.kind==='correlation'?'Pearson’s r describes a linear relationship between paired numbers. Outliers, nonlinear patterns and confounding can change its meaning. Correlation does not establish causation.':'Welch’s comparison allows unequal variances for independent groups. Group comparability and independence still matter. Repeated measurements on the same people or units need a paired design.'}</p><div class="notice">Descriptive results are only as trustworthy as the source, units, sampling and study design.</div></div></aside></div>`;}
function parseNumbers(text){const s=text.trim();if(!s)throw new Error('Enter a series of numbers.');if(/(^|,)\s*(,|$)/.test(s))throw new Error('There is an empty comma-separated value. Check for a missing observation.');const tokens=s.split(/[\s,;]+/);if(tokens.length<3||tokens.length>500)throw new Error('Use between 3 and 500 numbers per series.');const vals=tokens.map(v=>{if(!/^[+-]?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?$/i.test(v))throw new Error(`“${v.slice(0,30)}” is not a valid number.`);const n=Number(v);if(!Number.isFinite(n)||Math.abs(n)>1e12)throw new Error('Use finite numbers with absolute values below 1 trillion.');return n;});return vals;}
function pFormat(p){return typeof p!=='number'||!Number.isFinite(p)?'Not estimable':p<.000001?'< 0.000001':number(p,6);}
function number(n,p=3){return typeof n==='number'&&Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:p}):'Undefined';}
function labChart(x,y,kind){const w=620,h=230,p=40;let xx=kind==='trend'?x.map((_,i)=>i+1):x,yy=kind==='trend'?x:y;let minX=Math.min(...xx),maxX=Math.max(...xx),minY=Math.min(...yy),maxY=Math.max(...yy);if(minX===maxX){minX-=1;maxX+=1;}if(minY===maxY){minY-=1;maxY+=1;}const cx=v=>p+(v-minX)/(maxX-minX)*(w-p*2),cy=v=>h-p-(v-minY)/(maxY-minY)*(h-p*2);return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${kind==='trend'?'Time ordered line chart':'Scatterplot of paired values'}" style="width:100%;background:#f9fbf5;border:1px solid #e0e7d8;border-radius:7px;margin:18px 0"><path d="M${p} ${p}V${h-p}H${w-p}" fill="none" stroke="#a8b59c"/>${kind==='trend'?`<polyline points="${xx.map((v,i)=>`${cx(v)},${cy(yy[i])}`).join(' ')}" fill="none" stroke="#527e48" stroke-width="2"/>`:''}${xx.map((v,i)=>`<circle cx="${cx(v)}" cy="${cy(yy[i])}" r="${xx.length>80?2:3}" fill="#3c6844"><title>${E(v)}, ${E(yy[i])}</title></circle>`).join('')}<g font-family="sans-serif" font-size="10" fill="#718166"><text x="${p}" y="${h-14}">${number(minX)}</text><text x="${w-p}" y="${h-14}" text-anchor="end">${number(maxX)}</text><text x="${p-8}" y="${p+4}" text-anchor="end">${number(maxY)}</text><text x="${p-8}" y="${h-p}" text-anchor="end">${number(minY)}</text></g></svg>`;}
function runLab(){const out=$('#lab-output');try{const x=parseNumbers($('#lab-x').value),kind=state.lab.kind,y=kind==='trend'?null:parseNumbers($('#lab-y').value);state.lab.x=$('#lab-x').value;if(y)state.lab.y=$('#lab-y').value;save();if(!FM.stats)throw new Error('The statistics module has not loaded. Reload the app and try again.');const s=FM.stats.summarize(x);let warning='';let rows=[['Observations',s.n],['Mean',number(s.mean)],['Median',number(s.median)],['Sample standard deviation',number(s.sampleSD??s.sd)],['Minimum',number(s.min)],['Maximum',number(s.max)]],extra='',visual='';if(kind==='trend'){const a=FM.stats.trend(x);rows.push(['Slope per observation',number(a.slope)]);visual=labChart(x,null,'trend');extra='The slope is descriptive. Check the time spacing, process changes, unusual observations and uncertainty before acting.';}else if(kind==='correlation'){if(x.length!==y.length)throw new Error('X and Y need the same number of observations, paired in order.');const a=FM.stats.correlation(x,y);warning=a.warning||'';rows=[['Paired observations',x.length],['Pearson r',number(a.r)],['Two-sided p-value',pFormat(a.p)]];visual=labChart(x,y,'correlation');extra='This describes a linear association, not causation. Any p-value relies on model assumptions and does not measure practical importance.';}else{const a=FM.stats.compare(x,y),b=FM.stats.summarize(y);warning=a.warning||'';rows=[['Group A: n / mean',x.length+' / '+number(s.mean)],['Group B: n / mean',y.length+' / '+number(b.mean)],['Mean difference (B − A)',number(a.difference)],['Welch t',number(a.t)],['Degrees of freedom',number(a.df)],['Two-sided p-value',pFormat(a.p)],['95% interval for difference',Array.isArray(a.ci)?number(a.ci[0])+' to '+number(a.ci[1]):'Not estimable']];extra='This comparison assumes independent observations and reasonably suitable sampling. A small p-value is not the probability that the null hypothesis is true, and it does not establish causation or practical importance.';}out.innerHTML=tableHTML({title:'Computed result',headers:['Measure','Value'],rows})+visual+`<div class="notice">${E(extra)}${warning?'<br><br>'+E(warning):''}</div>`;}catch(err){out.innerHTML=`<div class="notice error">${E(err.message)}</div>`;}}
function openModal(title,content){$('#modal-content').innerHTML=`<div class="modal-header"><h2>${E(title)}</h2>${button(icon('close'),'close-modal','small ghost','aria-label="Close dialog"')}</div><div class="modal-body">${content}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();modalRecord=null;}
function displayValue(f,v){if(f.kind==='select'){const op=f.options?.find(x=>String(typeof x==='string'?x:x.value)===String(v));return op?(typeof op==='string'?op:op.label):v;}return typeof v==='boolean'?(v?'Yes':'No'):v;}
function recordWork(e){const rows=e.fields.map(f=>[f.label,displayValue(f,e.answers[f.id]??'—')]);['_recommendation','_evidence','_defense'].forEach((f,i)=>{if(e.capstone)rows.push([['Recommendation','Supporting evidence','Defense and limitations'][i],e.answers[f]||'Not provided']);});return `<div class="result-banner"><h3>${E(e.lessonTitle)}</h3><p>${E(e.trackTitle)} · ${E(e.contextName)} · ${date(e.submittedAt)}<br>${e.mode==='preview'?'Coach preview':independent(e)?'Independent first attempt':e.assisted?'Assisted practice':'Practice / revised submission'} · ${time(e.elapsedMs)} visible practice time · version ${E(e.version)}</p></div><p>${E(e.brief)}</p>${e.facts?.length?tableHTML({title:'Source facts',headers:['Fact','Value'],rows:e.facts.map(f=>[f.label,f.value])}):''}${e.tables.map(tableHTML).join('')}${tableHTML({title:'Submitted work product',headers:['Field','Response'],rows})}<h3>Objective checks</h3><div class="feedback-list">${e.checks.map(c=>`<div class="check ${c.ok?'good':'bad'}"><span>${c.ok?'✓':'!'}</span><div><strong>${E(c.label)}</strong><p>${E(c.feedback)}</p></div></div>`).join('')}</div>${e.review?`<h3>Recorded review</h3><p>${E(e.review.name)} · ${e.review.type==='peer'?'Peer review':'Self review'} · ${date(e.review.at)}<br>${DIMS.map(([n])=>`${n}: ${E(e.review.scores[n])}/4`).join(' · ')}</p><p>${E(e.review.notes)}</p>${e.reviewHistory?.length?'<details><summary>Earlier reviewer ratings ('+e.reviewHistory.length+')</summary>'+e.reviewHistory.map(r=>'<p>'+E(r.name)+' · '+E(r.type)+' · '+date(r.at)+'<br>'+DIMS.map(([n])=>n+': '+E(r.scores[n])+'/4').join(' · ')+'<br>'+E(r.notes)+'</p>').join('')+'</details>':''}`:''}`;}
function viewRecord(e){modalRecord=e.id;openModal('Work product',recordWork(e)+`<div class="toolbar" style="margin-top:20px">${button('Copy work product','copy-record','small',`data-record="${E(e.id)}"`)}${button('Print','print','small')}${e.capstone?button('Review this capstone','review-record','primary',`data-record="${E(e.id)}"`):''}</div>`);}
function reviewRecord(e){modalRecord=e.id;openModal('Review the performance',`<p>Judge the actual work and explanation against the six dimensions. A peer review must be entered by a reviewer other than the learner. Reviewer identity is recorded locally and is not authenticated.</p><details><summary style="cursor:pointer;font-weight:600;font-size:13px">Inspect the submitted work product</summary><div style="margin-top:18px">${recordWork(e)}</div></details><div class="review-identity"><div><label for="reviewer-name">Reviewer name</label><input class="plain-input" id="reviewer-name" maxlength="150" value="${E(e.review?.name||'')}" placeholder="Name of person conducting the review"></div><div><label for="reviewer-type">Review type</label><select class="plain-input" id="reviewer-type"><option value="self" ${e.review?.type==='self'?'selected':''}>Self review (practice only)</option><option value="peer" ${e.review?.type==='peer'?'selected':''}>Peer review (another person)</option></select></div></div><div class="review-grid">${DIMS.map(([n,d])=>`<div class="field"><label for="review-${n}">${n}</label><small>${d}</small><select id="review-${n}" data-review-dim="${n}"><option value="">Not scored</option>${SCALE.map((v,i)=>`<option value="${i}" ${e.review?.scores[n]===i?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}</div><label style="display:flex;gap:10px;align-items:flex-start;font-size:12px;margin:23px 0"><input type="checkbox" id="review-critical" ${e.review?.criticalClear?'checked':''}>I inspected the work product and found no unresolved critical error.</label><div class="field"><label for="review-notes">Evidence, disagreements, and next steps</label><textarea id="review-notes" rows="4" maxlength="6000" placeholder="Explain the ratings with evidence from this attempt. Note any corrections or questions used in the defense.">${E(e.review?.notes||'')}</textarea></div><div class="notice">A good explanation cannot cancel an invalid work product. The proposed pilot criterion also requires fresh independent work in two different contexts.</div><div class="toolbar">${button('Save review','save-review','primary',`data-record="${E(e.id)}"`)}</div>`);}
function recordText(e){return [`Force Multiplier ${VERSION}`,e.trackTitle+' / '+e.lessonTitle,e.contextName+' · '+date(e.submittedAt),'Mode: '+e.mode+'; assisted: '+e.assisted+'; attempt: '+e.attemptNo+'; case: '+e.seed,'Visible exercise time: '+time(e.elapsedMs),'\nASSIGNMENT\n'+e.brief,'\nSOURCE FACTS',...(e.facts||[]).map(f=>f.label+': '+f.value),'\nSOURCE TABLES',...e.tables.map(t=>t.title+'\n'+t.headers.join(' | ')+'\n'+t.rows.map(r=>r.join(' | ')).join('\n')),'\nWORK PRODUCT',...e.fields.map(f=>f.label+': '+displayValue(f,e.answers[f.id]??'—')),e.capstone?'\nRECOMMENDATION\n'+(e.answers._recommendation||'Not provided'):'',e.capstone?'\nEVIDENCE\n'+(e.answers._evidence||'Not provided'):'',e.capstone?'\nDEFENSE\n'+(e.answers._defense||'Not provided'):'','\nCHECKS',...e.checks.map(c=>(c.ok?'PASS ':'REVIEW ')+c.label+': '+c.feedback),e.review?'\nREVIEW\n'+JSON.stringify(e.review,null,2):''].filter(Boolean).join('\n');}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch(e){openModal('Copy this text',`<p>Select and copy the text below.</p><textarea class="note-area" style="height:300px" readonly>${E(text)}</textarea>`);}}
function download(name,value){if(window.FMExport){window.FMExport(name,value).then(()=>toast('Export opened. Choose where to save it.')).catch(e=>toast('Export not completed: '+e.message));return;}toast('Export is unavailable. Reopen the app and try again.');}
function exportBackup(){save();download('force-multiplier-v22-backup-'+new Date().toISOString().slice(0,10)+'.json',{format:'force-multiplier-workspace',version:VERSION,exportedAt:new Date().toISOString(),data:state});}
let pendingRestore=null;
function validateBackup(data){
  const obj=x=>x&&typeof x==='object'&&!Array.isArray(x);
  const str=(x,n=8000)=>typeof x==='string'&&x.length<=n;
  const finite=x=>typeof x==='number'&&Number.isFinite(x);
  const assert=(ok,message)=>{if(!ok)throw new Error(message);};
  assert(obj(data)&&data.schema===3&&obj(data.settings)&&obj(data.cases)&&Array.isArray(data.evidence),'Unsupported workspace structure.');
  assert(data.evidence.length<=500&&Object.keys(data.cases).length<=3000,'This backup exceeds the workspace limits.');
  assert(CONTEXTS.some(c=>c.id===data.settings.context)&&['practice','independent','preview'].includes(data.settings.mode),'Invalid practice settings.');
  assert(typeof data.settings.sound==='boolean'&&typeof data.settings.calcPractice==='boolean','Invalid practice settings.');
  assert(str(data.notes??'',100000),'Invalid working-group notes.');
  assert(obj(data.last)&&getTrack(data.last.track)&&Number.isInteger(data.last.lesson)&&data.last.lesson>=0&&data.last.lesson<getTrack(data.last.track).lessons.length,'Invalid last lesson.');
  assert(obj(data.lab)&&['trend','correlation','difference'].includes(data.lab.kind)&&str(data.lab.x,30000)&&str(data.lab.y,30000),'Invalid statistics workspace.');
  const values=a=>obj(a)&&Object.entries(a).every(([k,v])=>str(k,120)&&!['__proto__','constructor','prototype'].includes(k)&&(str(v,8000)||typeof v==='boolean'||finite(v)));
  const review=r=>obj(r)&&str(r.name,150)&&['self','peer'].includes(r.type)&&obj(r.scores)&&DIMS.every(([d])=>Number.isInteger(r.scores[d])&&r.scores[d]>=0&&r.scores[d]<=4)&&str(r.notes,6000)&&typeof r.criticalClear==='boolean'&&str(r.at,50)&&Number.isFinite(Date.parse(r.at));
  const records=[...data.evidence,...(data.previewEvidence||[])];
  assert(Array.isArray(data.previewEvidence||[])&&(data.previewEvidence||[]).length<=50,'Invalid coach preview history.');
  const ids=new Set();
  for(const e of records){
    assert(obj(e)&&str(e.id,100)&&/^[a-zA-Z0-9_-]+$/.test(e.id)&&!ids.has(e.id),'Invalid or duplicate evidence identifier.');ids.add(e.id);
    const t=getTrack(e.track);assert(t&&t.lessons.some(l=>l.id===e.lessonId),'Unknown lesson in evidence.');
    assert(str(e.trackTitle,200)&&str(e.lessonTitle,300)&&str(e.brief,20000)&&str(e.contextName,150)&&CONTEXTS.some(c=>c.id===e.contextId),'Invalid evidence description.');
    assert(Number.isInteger(e.seed)&&e.seed>=0&&e.seed<=4294967295&&Number.isInteger(e.attemptNo)&&e.attemptNo>=1&&finite(e.elapsedMs)&&e.elapsedMs>=0,'Invalid evidence timing or case.');
    assert(['practice','independent','preview'].includes(e.mode)&&typeof e.assisted==='boolean'&&typeof e.pass==='boolean'&&typeof e.capstone==='boolean'&&str(e.submittedAt,50)&&Number.isFinite(Date.parse(e.submittedAt)),'Invalid evidence status.');
    assert(values(e.answers)&&Array.isArray(e.fields)&&e.fields.length<=150,'Invalid work product.');
    for(const f of e.fields){assert(obj(f)&&str(f.id,120)&&str(f.label,1000)&&['number','text','textarea','select','checkbox'].includes(f.kind),'Invalid work-product field.');if(f.options)assert(Array.isArray(f.options)&&f.options.length<=150&&f.options.every(o=>str(o,1000)||(obj(o)&&(str(o.value,1000)||finite(o.value))&&str(o.label,1000))),'Invalid field choices.');}
    assert(Array.isArray(e.checks)&&e.checks.length<=200&&e.checks.every(c=>obj(c)&&str(c.label,1000)&&str(c.feedback??'',5000)&&typeof c.ok==='boolean'),'Invalid assessment checks.');
    assert(Array.isArray(e.tables)&&e.tables.length<=30&&e.tables.every(t=>obj(t)&&str(t.title??'',500)&&Array.isArray(t.headers)&&t.headers.length<=50&&t.headers.every(h=>str(h,1000))&&Array.isArray(t.rows)&&t.rows.length<=500&&t.rows.every(r=>Array.isArray(r)&&r.length<=50&&r.every(v=>str(v,5000)||finite(v)))),'Invalid source tables.');
    assert(!e.facts||(Array.isArray(e.facts)&&e.facts.length<=100&&e.facts.every(f=>obj(f)&&str(f.label,1000)&&(str(f.value,5000)||finite(f.value)))),'Invalid source facts.');
    assert(!e.review||review(e.review),'Invalid reviewer record.');
    assert(!e.reviewHistory||(Array.isArray(e.reviewHistory)&&e.reviewHistory.length<=100&&e.reviewHistory.every(review)),'Invalid review history.');
  }
  for(const [key,c]of Object.entries(data.cases)){const parts=key.split('|'),t=getTrack(parts[0]);assert(parts.length===4&&t&&t.lessons.some(l=>l.id===parts[1])&&CONTEXTS.some(x=>x.id===parts[2])&&['practice','independent','preview'].includes(parts[3]),'Invalid exercise identity.');assert(obj(c)&&values(c.answers)&&Number.isInteger(c.seed)&&c.seed>=0&&c.seed<=4294967295&&Number.isInteger(c.attempts)&&c.attempts>=0&&finite(c.elapsed)&&c.elapsed>=0,'Invalid exercise state.');c.result=null;}
  return data;
}
async function restoreFile(file){try{if(file.size>8000000)throw new Error('This backup is too large. Maximum size is 8 MB.');const b=JSON.parse(await file.text());if(b.format!=='force-multiplier-workspace')throw new Error('This is not a supported Force Multiplier v22 workspace backup.');pendingRestore=validateBackup(b.data);openModal('Restore this backup?',`<p>This backup contains <strong>${b.data.evidence.length} submitted work products</strong> and ${Object.keys(b.data.cases).length} exercise states. It was exported ${E(b.exportedAt?date(b.exportedAt):'at an unknown time')}.</p><div class="notice warn">Restoring replaces the current local workspace. Export a backup first if you need to retain it.</div><div class="toolbar">${button('Back up current workspace','backup')}${button('Replace with this backup','confirm-restore','primary')}</div>`);}catch(e){pendingRestore=null;toast(e.message);}}
function bindLocal(){if($('#context'))$('#context').addEventListener('change',e=>{state.settings.context=e.target.value;save();render();toast('Context changed. Each context has its own cases and progress.');});if($('#lesson-jump'))$('#lesson-jump').addEventListener('change',e=>go('path/'+route.track+'/'+e.target.value));if($('#working-notes'))$('#working-notes').addEventListener('input',e=>{state.notes=e.target.value;save();});if($('#sound-setting'))$('#sound-setting').addEventListener('change',e=>{state.settings.sound=e.target.checked;save();});if($('#calc-setting'))$('#calc-setting').addEventListener('change',e=>{state.settings.calcPractice=e.target.checked;save();});if($('#restore-file'))$('#restore-file').addEventListener('change',e=>{if(e.target.files[0])restoreFile(e.target.files[0]);});if($('#work-form'))$('#work-form').addEventListener('submit',e=>{e.preventDefault();checkWork();});}
document.addEventListener('input',e=>{const f=e.target.closest('[data-field]');if(f&&active){active.c.answers[f.dataset.field]=f.type==='checkbox'?f.checked:f.value;if(active.c.result){active.c.result=null;$('#feedback-region').innerHTML='<div class="notice" style="margin:18px">Your worksheet has changed. Submit again to check this revision; earlier attempts remain in evidence.</div>';}save();}if(e.target.id==='lab-x'||e.target.id==='lab-y'){state.lab[e.target.id==='lab-x'?'x':'y']=e.target.value;save();}});
document.addEventListener('change',e=>{const f=e.target.closest('[data-field]');if(f&&active){active.c.answers[f.dataset.field]=f.type==='checkbox'?f.checked:f.value;save();}});
document.addEventListener('click',async e=>{if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus();return;}const nav=e.target.closest('[data-nav]');if(nav){menu=false;go(nav.dataset.nav);if(location.hash==='#'+nav.dataset.nav)render();return;}const m=e.target.closest('[data-mode]');if(m){if(active){state.settings.mode=m.dataset.mode;save();render();}return;}const lab=e.target.closest('[data-lab-kind]');if(lab){state.lab.kind=lab.dataset.labKind;save();render();return;}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
if(a==='menu'){menu=!menu;document.body.classList.toggle('menu-open',menu);return;}
if(a==='sound'){state.settings.sound=!state.settings.sound;save();render(true);return;}
if(a==='resume'){const last=state.last;go('path/'+(getTrack(last.track)?last.track:'scheduling')+'/'+(last.lesson||0));return;}
if(a==='fullscreen'){fullscreen=!fullscreen;document.body.classList.toggle('fullscreen',fullscreen);if(fullscreen&&document.documentElement.requestFullscreen){try{await document.documentElement.requestFullscreen();}catch(err){}}else if(!fullscreen&&document.fullscreenElement){try{await document.exitFullscreen();}catch(err){}}return;}
if(a==='close-modal'){closeModal();return;}
if(a==='check'){checkWork();return;}
if(a==='new-case'&&active){delete state.cases[active.key];save();render(true);toast('New randomized case. Earlier submissions remain in your portfolio.');return;}
if(a==='clear-case'&&active){active.c.answers={};active.c.result=null;save();render(true);toast('This worksheet is clear. Earlier submissions and assistance history are retained.');return;}
if(a==='hint'&&active&&state.settings.mode!=='independent'){active.c.assisted=true;active.c.hints++;save();openModal('A useful hint',`<p>${E(active.sc.hint||active.sc.teach?.[0]||'Compare each input with the scope and constraints in the assignment.')}</p><div class="notice">This case is now recorded as assisted practice.</div>`);return;}
if(a==='model'&&active&&state.settings.mode!=='independent'){const{c,sc}=active;c.assisted=true;c.example=true;c.answers={...c.answers,...sc.model};c.result=null;save();render(true);toast(state.settings.mode==='preview'?'Worked example filled in coach preview.':'Worked example filled. This is assisted practice.');return;}
if(a==='calculation-mode'&&active){state.settings.calcPractice=!state.settings.calcPractice;active.c.calcInitialized=false;active.sc.fields.filter(f=>f.kind==='number').forEach(f=>delete active.c.answers[f.id]);active.c.result=null;save();render(true);return;}
if(a==='calculator'){openModal('Calculator',`<p>Use the calculator for arithmetic. It does not select the correct measure, denominator or method for you.</p><div class="calc"><input class="plain-input" id="calc-a" type="number" step="any" aria-label="First number" placeholder="First"><select class="plain-input" id="calc-op" aria-label="Operation"><option value="+">+</option><option value="-">−</option><option value="*">×</option><option value="/">÷</option><option value="%">÷ ×100</option></select><input class="plain-input" id="calc-b" type="number" step="any" aria-label="Second number" placeholder="Second"></div><div class="calc-output" id="calc-result">—</div>${button('Calculate','do-calculate','primary')}`);return;}
if(a==='do-calculate'){const av=$('#calc-a').value,bv=$('#calc-b').value,x=Number(av),y=Number(bv),op=$('#calc-op').value;if(!av.trim()||!bv.trim()||!Number.isFinite(x)||!Number.isFinite(y)){$('#calc-result').textContent='Enter two finite numbers';return;}if(['/', '%'].includes(op)&&y===0){$('#calc-result').textContent='Undefined: denominator is zero';return;}const val=op==='+'?x+y:op==='-'?x-y:op==='*'?x*y:op==='/'?x/y:x/y*100;$('#calc-result').textContent=number(val,8)+(op==='%'?'%':'');return;}
if(a==='view-record'||a==='review-record'){const r=allEvidence().find(x=>x.id===el.dataset.record);if(r){if(a==='review-record')reviewRecord(r);else viewRecord(r);}else toast('This work product is no longer in the retained evidence.');return;}
if(a==='save-review'){const r=allEvidence().find(x=>x.id===el.dataset.record);if(!r)return;const name=$('#reviewer-name').value.trim(),scores={};if(!name){toast('Enter the reviewer’s name.');return;}for(const[n]of DIMS){const val=$('#review-'+n).value;if(val===''){toast('Score all six dimensions before saving.');return;}scores[n]=Number(val);}const type=$('#reviewer-type').value,notes=$('#review-notes').value.trim();if(!notes){toast('Record the evidence behind the ratings.');return;}if(r.review){r.reviewHistory||=[];r.reviewHistory.push(r.review);}r.review={name,type,scores,criticalClear:$('#review-critical').checked,notes,at:new Date().toISOString()};save();closeModal();render(true);toast('Review saved with this specific work product.');return;}
if(a==='copy-record'){const r=allEvidence().find(x=>x.id===el.dataset.record);if(r)await copy(recordText(r));return;}
if(a==='copy-notes'){await copy(state.notes||'No working-group notes have been entered.');return;}
if(a==='print'){window.print();return;}
if(a==='backup'){exportBackup();return;}
if(a==='export-evidence'){download('force-multiplier-v22-evidence.json',{format:'force-multiplier-evidence',version:VERSION,exportedAt:new Date().toISOString(),proposedRubric:{dimensions:DIMS,minimumEach:3,independentCases:2,differentContexts:true,criticalErrorsAllowed:0,validated:false},evidence:state.evidence,coachPreviews:state.previewEvidence});return;}
if(a==='confirm-restore'&&pendingRestore){state={...defaults(),...pendingRestore,settings:{...defaults().settings,...pendingRestore.settings}};pendingRestore=null;save();closeModal();go('home');render();toast('Workspace restored.');return;}
if(a==='reset-workspace'){openModal('Reset local workspace?',`<p>This clears exercises, submitted work, reviewer notes and settings for this app on this device.</p><div class="toolbar">${button('Back up first','backup')}${button('Reset this app’s data','confirm-reset','danger')}</div>`);return;}
if(a==='confirm-reset'){state=defaults();save();closeModal();go('home');render();toast('The workspace has been reset.');return;}
if(a==='test-sound'){sound(el.dataset.ok==='true',Number(el.dataset.variant),true);return;}
if(a==='run-lab'){runLab();return;}
if(a==='sample-lab'){const r=FM.rng(seed()),base=FM.int(r,10,30);state.lab.x=Array.from({length:10},(_,i)=>FM.int(r,base,base+8)+(state.lab.kind==='trend'?i:0)).join(', ');state.lab.y=state.lab.x.split(', ').map((v,i)=>state.lab.kind==='correlation'?Number(v)*2+FM.int(r,-3,3):FM.int(r,base+3,base+11)).join(', ');save();render(true);runLab();return;}
if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;return;}openModal('Add Force Multiplier to your device',`<p>Open this app in your browser to add it to your home screen.</p><ol class="install-steps"><li><strong>iPhone or iPad:</strong> open in Safari, tap Share, then choose Add to Home Screen.</li><li><strong>Android:</strong> open the browser menu and choose Install app or Add to Home screen.</li><li><strong>Desktop:</strong> use the browser’s install icon or app-install option, when available.</li></ol><div class="notice">Let the app load once while connected. Offline files are cached when your browser supports service workers. Keep a backup of your local work.</div><p>This is an installable web app. Your practice and evidence remain on the device where you enter them.</p>`);return;}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu){menu=false;document.body.classList.remove('menu-open');}});
window.addEventListener('hashchange',()=>{menu=false;render();});
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement){fullscreen=false;document.body.classList.remove('fullscreen');}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
setInterval(()=>{const now=Date.now(),delta=Math.min(now-timer,2000);timer=now;if(active&&!document.hidden&&!$('#modal').open){active.c.elapsed=(active.c.elapsed||0)+delta;if($('#elapsed'))$('#elapsed').textContent=time(active.c.elapsed);}},1000);
setInterval(save,10000);window.addEventListener('pagehide',save);
render();
if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol)){navigator.serviceWorker.register('./sw.js').catch(()=>{});}
window.FM_APP={version:VERSION,getState:()=>JSON.parse(JSON.stringify(state)),contexts:CONTEXTS,tracks:TRACKS};
})();
